#!/usr/bin/env node
'use strict';
/* AN AGENT COULD READ EVERY CONTRACT AND NOT ONE MEASUREMENT.
 *
 * Eleven tools describe what the laboratories ARE and how they connect. None of
 * them said what this atlas has measured about its own behaviour, and four
 * artifacts generated by walking it headlessly sat in the repository unserved:
 *
 *   sensitivity  484 inputs driven one at a time — 407 respond, 25 are DEAD.
 *                A dead input is declared, typed, in-domain and inert, and NO
 *                contract reveals that. For an agent about to sweep a parameter it
 *                is the difference between measuring something and measuring
 *                nothing, which is the strongest argument for serving any of this.
 *   transfers    the exponent between an input and an output, per route
 *   reach        511 composed chains, each judged a power law, not one, or unjudged
 *   liveness     every view, and whether it visibly responds to its own controls
 *
 * AND THE STAMP IS THE POINT. liveness is deliberately dated — expensive to
 * regenerate, and it says which release it was measured on rather than being forced
 * current. An agent that reads a stale measurement as a fresh one is worse off than
 * one that has none, so every artifact reports its own version and whether that is
 * THIS release, compared against version.json rather than against the node core's
 * separate version number.
 */
const fs = require('node:fs'), path = require('node:path');
const ROOT = path.join(__dirname, '..');
let pass = 0, fail = 0;
const ok = (n, c, d) => { if (c) { pass++; console.log('  PASS — ' + n + (d ? ' :: ' + d : '')); }
  else { fail++; console.log('  FAIL — ' + n + (d ? ' :: ' + d : '')); } };

(async () => {
  const { CORE } = await import('../core/index.mjs');
  const { TOOLS } = await import('../server/server.mjs');
  const all = CORE.measurements();
  const KINDS = ['sensitivity', 'transfers', 'reach', 'liveness'];

  /* ── complete: every artifact reaches the surface, none silently truncated ── */
  const onDisk = {};
  for (const k of KINDS) onDisk[k] = JSON.parse(fs.readFileSync(path.join(ROOT, `api/${k}.json`), 'utf8'));
  ok('all four measured artifacts are served, not a selection of them',
    KINDS.every(k => all.measurements[k] && all.artifacts[k]),
    KINDS.map(k => k + ' ' + (all.artifacts[k].version || '—')).join(' · '));
  ok('and each one arrives whole — a truncated measurement is how a caller concludes an input is not dead',
    all.measurements.sensitivity.dead.length === onDisk.sensitivity.dead.length
    && all.measurements.reach.chains.length === onDisk.reach.chains.length
    && all.measurements.transfers.routes.length === onDisk.transfers.routes.length
    && all.measurements.liveness.views.length === onDisk.liveness.views.length,
    `${all.measurements.sensitivity.dead.length} dead inputs · ${all.measurements.reach.chains.length} chains · `
    + `${all.measurements.transfers.routes.length} routes · ${all.measurements.liveness.views.length} views`);

  /* ── THE DEAD INPUTS, which are the reason this is worth serving ─────────── */
  const dead = all.measurements.sensitivity.dead;
  ok('the DEAD inputs are named individually, with the range over which nothing happened',
    dead.length >= 20 && dead.every(d => d.input && d.min !== undefined && d.max !== undefined),
    `${dead.length} inputs that are declared, typed, in-domain and inert — e.g. `
    + dead.slice(0, 2).map(d => `${d.input} over [${d.min}, ${d.max}]`).join(', '));

  /* ── THE STAMP: a dated artifact must say it is dated ────────────────────── */
  const release = JSON.parse(fs.readFileSync(path.join(ROOT, 'version.json'), 'utf8')).version;
  ok('the answer compares each artifact against the ATLAS release, not the node core\'s own version',
    all.atlas_release === release,
    `atlas ${all.atlas_release} · the node core carries a different number and comparing against it `
    + 'would report every artifact stale forever');
  const wrongStamp = KINDS.filter(k => all.artifacts[k].measured_on_this_release !== (onDisk[k].version === release));
  ok('and every artifact says truthfully whether it was measured on THIS release',
    wrongStamp.length === 0,
    wrongStamp.length ? ('stamp disagrees with the file for: ' + wrongStamp.join(' '))
      : KINDS.map(k => k + (all.artifacts[k].measured_on_this_release ? '' : ' (DATED ' + all.artifacts[k].version + ')')).join(' · '));
  ok('a dated artifact is served rather than hidden — a measurement from an earlier release is still a measurement',
    KINDS.some(k => !all.artifacts[k].measured_on_this_release)
      ? all.measurements[KINDS.find(k => !all.artifacts[k].measured_on_this_release)] !== null : true,
    KINDS.filter(k => !all.artifacts[k].measured_on_this_release).join(' ') || 'every artifact is current this release');

  /* ── one function, two doors ─────────────────────────────────────────────── */
  const server = fs.readFileSync(path.join(ROOT, 'server/server.mjs'), 'utf8');
  const route = /\/api\/v1\/measurements'[\s\S]{0,400}?CORE\.measurements\(/.test(server);
  const tool = TOOLS.find(t => t.name === 'list_measurements');
  ok('the HTTP route and the MCP tool both call CORE.measurements — one function, two doors',
    route && !!tool && /CORE\.measurements\(/.test(String(tool.call)),
    [!route && 'the HTTP route does not delegate',
     !tool && 'the MCP tool is missing',
     tool && !/CORE\.measurements\(/.test(String(tool.call)) && 'the MCP tool has its own implementation'
    ].filter(Boolean).join(' · ') || 'route ✓ · tool ✓');

  /* ── honest refusals and honest emptiness ────────────────────────────────── */
  let refused = null;
  try { CORE.measurements({ kind: 'bogus' }); } catch (e) { refused = e; }
  ok('an unknown kind is REFUSED with the known kinds named',
    !!refused && refused.code === 'BAD_INPUT' && /sensitivity, transfers, reach, liveness/.test(refused.message),
    refused ? refused.message.slice(0, 90) : 'an unknown kind was accepted');
  const miss = CORE.measurements({ lab: 'definitely-not-a-lab' });
  ok('and a laboratory no measurement mentions is TOLD SO rather than handed empty arrays',
    typeof miss.note === 'string' && /no measurement mentions/.test(miss.note),
    miss.note || 'no note');
  const cmb = CORE.measurements({ kind: 'sensitivity', lab: 'cmb' });
  ok('the laboratory filter reaches into each artifact\'s own row shape, which are four different shapes',
    cmb.note === null && cmb.measurements.sensitivity.saturating.length > 0,
    `cmb: ${cmb.measurements.sensitivity.saturating.length} saturating input(s) found by filtering on the input name`);

  /* ── and the generated contracts advertise it ────────────────────────────── */
  const openapi = JSON.parse(fs.readFileSync(path.join(ROOT, 'api/openapi.json'), 'utf8'));
  const mcp = JSON.parse(fs.readFileSync(path.join(ROOT, '.well-known/mcp.json'), 'utf8'));
  ok('the generated OpenAPI and MCP contracts advertise it, so an agent finds it without being told',
    !!openapi.paths['/api/v1/measurements'] && mcp.tools.some(t => t.name === 'list_measurements')
    && mcp.tools.length === TOOLS.length,
    `${Object.keys(openapi.paths).length} paths · ${mcp.tools.length} tools`);

  console.log('\n' + (fail ? ('✖ ' + fail + ' FAILED, ' + pass + ' passed') : ('✔ ALL ' + pass + ' CHECKS PASSED')));
  process.exit(fail ? 1 : 0);
})();
